		t.Fatal(err)
	}
	deps := ServerDeps{Registry: NewRegistry(false), Health: new(Health)}
	for _, address := range []string{"127.0.0.1:9464", "[::1]:9464", "10.0.1.5:9464", "172.16.4.2:9464", "192.168.1.10:9464", "10.200.106.253:9464", "[fd00::1]:9464"} {
