// LiteralHost reports whether an HTTP Host header names an IP literal or
// localhost, which a DNS-rebinding page cannot present.
func LiteralHost(host string) bool {
	if name, _, err := net.SplitHostPort(host); err == nil {
		host = name
	} else if len(host) > 1 && host[0] == '[' && host[len(host)-1] == ']' {
		host = host[1 : len(host)-1]
	}
	if host == "localhost" {
		return true
	}
	_, err := netip.ParseAddr(host)
	return err == nil
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func (config Config) Validate() error {
	if _, _, err := ParseLogConfig(config.LogFormat, config.LogLevel); err != nil {
		return err
	}
	if (config.TLSCertFile == "") != (config.TLSKeyFile == "") {
		return errors.New("observability TLS requires both a certificate and a key file")
	}
	address, err := ValidateListenAddress(config.Address())
	if err != nil {
		return err
	}
	if !address.Addr().IsLoopback() && config.BearerTokenFile == "" {
		return errors.New("a non-loopback observability listener requires bearer_token_file")
	}
	return nil
}

// ValidateListenAddress accepts only a literal private IP and a non-zero
// port. Wildcard, public, link-local and multicast addresses are rejected,
// so metrics never reach a public interface by configuration mistake.
func ValidateListenAddress(raw string) (netip.AddrPort, error) {
	address, err := netip.ParseAddrPort(raw)
	if err != nil || address.Port() == 0 || address.Addr().Zone() != "" ||
		address.String() != raw {
		return netip.AddrPort{}, fmt.Errorf("observability listen address %q must be a literal IP:port", raw)
	}
	ip := address.Addr().Unmap()
	if ip.IsUnspecified() || ip.IsMulticast() || ip.IsLinkLocalUnicast() {
		return netip.AddrPort{}, errors.New("observability listener must bind one private address, not a wildcard")
	}
	if !ip.IsLoopback() && !ip.IsPrivate() {
		return netip.AddrPort{}, errors.New("observability listener must bind loopback or a private VCN or NetBird address")
	}
	return address, nil
}

// readBearerToken reads a private token file. Group or world access is
// rejected the same way other key files of this binary are.
func readBearerToken(path string) ([]byte, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open observability bearer token: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("observability bearer token must be a private regular file")
	}
	data, err := io.ReadAll(io.LimitReader(file, maxBearerTokenBytes+1))
	if err != nil {
		return nil, err
	}
	return checkBearerToken(data)
}

// checkBearerToken accepts one 32-4096 byte line, surrounding whitespace
// trimmed.
func checkBearerToken(data []byte) ([]byte, error) {
	token := []byte(strings.TrimSpace(string(data)))
	if len(data) > maxBearerTokenBytes || len(token) < minBearerTokenBytes ||
		strings.ContainsAny(string(token), " \t\r\n") {
		return nil, errors.New("observability bearer token must be one 32-4096 byte line")
	}
	return token, nil
}

func bearerMatches(header string, token []byte) bool {
	presented, found := strings.CutPrefix(header, "Bearer ")
	return found && subtle.ConstantTimeCompare([]byte(presented), token) == 1
}

func (server *Server) Start(ctx context.Context, config Config) (<-chan error, error) {
	address, err := ValidateListenAddress(config.Address())
	if err != nil {
		return nil, err
	}
	// The token was read by NewServer from its own config; never let a
	// different Start config widen a tokenless server onto a network address.
	if !address.Addr().IsLoopback() && server.token == nil {
		return nil, errors.New("a non-loopback observability listener requires bearer_token_file")
	}
	var tlsConfig *tls.Config
	if config.TLSCertFile != "" {
		certificate, err := tls.LoadX509KeyPair(config.TLSCertFile, config.TLSKeyFile)
		if err != nil {
			return nil, fmt.Errorf("load observability TLS: %w", err)
		}
		tlsConfig = &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}}
	}
	listener, err := (&net.ListenConfig{}).Listen(ctx, "tcp", address.String())
	if err != nil {
		return nil, err
	}
	if tlsConfig != nil {
		listener = tls.NewListener(listener, tlsConfig)
	}
	// No WriteTimeout: dashboard streams are long-lived. Headers and request
	// bodies are bounded as for the host enrollment listener.
	server.http = &http.Server{Handler: TraceHTTP(server), ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout: 10 * time.Second, IdleTimeout: time.Minute, MaxHeaderBytes: 4096}
	server.listen = listener
	if server.token != nil {
		cleanupCtx, cancel := context.WithCancel(ctx)
		server.reclaimCancel, server.reclaimDone = cancel, make(chan struct{})
		go func() {
			defer close(server.reclaimDone)
			server.sessions.retryCleanup(cleanupCtx)
		}()
	}
	result := make(chan error, 1)
	go func() {
		err := server.http.Serve(listener)
		if errors.Is(err, http.ErrServerClosed) {
			err = nil
		}
		result <- err
	}()
	context.AfterFunc(ctx, func() { _ = server.Close() })
	return result, nil
}

// Addr returns the bound address after Start.
func (server *Server) Addr() net.Addr {
	if server == nil || server.listen == nil {
		return nil
	}
	return server.listen.Addr()
}

// Close stops the listener and open connections.
func (server *Server) Close() error {
	if server == nil {
		return nil
	}
	if server.reclaimCancel != nil {
		server.reclaimCancel()
		<-server.reclaimDone
	}
	if server.http == nil {
		return nil
	}
	return server.http.Close()

func (server *Server) metrics(writer http.ResponseWriter, _ *http.Request) {
	writer.Header().Set("Content-Type", "text/plain; version=0.0.4; charset=utf-8")
	writer.Header().Set("Cache-Control", "no-store")
	server.deps.Registry.WritePrometheus(writer)
}

